function openIDB(){return new Promise(function(res,rej){try{var r=indexedDB.open('emd_protect_v66',1);r.onsuccess=function(){res(r.result)};r.onerror=function(){rej(r.error)};r.onblocked=function(){rej(new Error('blocked'))}}catch(e){rej(e)}})}
