(function(){
  const KEY='emd_duplicate_settings';
  const defaults={enabled:true,days:1,phone:true,place:true,items:true,qty:true,name:false};
  function get54(){try{return Object.assign({},defaults,JSON.parse(PLS.getItem(KEY)||'{}'))}catch(e){return Object.assign({},defaults)}}
  function set54(s){PLS.setItem(KEY,JSON.stringify(s))}
  function load54(){
    const s=get54();
    const ids={enabled:'dupEnabled54',days:'dupDays54',phone:'dupPhone54',place:'dupPlace54',items:'dupItems54',qty:'dupQty54',name:'dupName54'};
    Object.keys(ids).forEach(k=>{const e=document.getElementById(ids[k]);if(!e)return;if(k==='days')e.value=String(s[k]);else e.checked=!!s[k]});
  }
  window.openDuplicateSettings54=function(){document.getElementById('emdDuplicateSettings54').style.display='block';load54()};
  window.closeDuplicateSettings54=function(){document.getElementById('emdDuplicateSettings54').style.display='none'};
  window.saveDuplicateSettings54=function(){
    set54({
      enabled:document.getElementById('dupEnabled54').checked,
      days:Number(document.getElementById('dupDays54').value)||1,
      phone:document.getElementById('dupPhone54').checked,
      place:document.getElementById('dupPlace54').checked,
      items:document.getElementById('dupItems54').checked,
      qty:document.getElementById('dupQty54').checked,
      name:document.getElementById('dupName54').checked
    });
    closeDuplicateSettings54();
    alert('تم حفظ إعدادات كشف التكرار ✅');
  };
  load54();
})();

