 m.innerHTML='<div class="box"><h3>↕️ ترتيب الأزرار والأقسام</h3><p>رتّبها على حسب ما يناسبك باستخدام الأسهم. يُحفظ الترتيب مع بياناتك.</p><div class="tabs">'+Object.keys(GROUPS).map(function(g){return '<button class="'+(g===cg?'on':'')+'" data-a="g" data-v="'+g+'">'+GROUPS[g].short+'</button>'}).join('')+'</div><h4>'+GROUPS[cg].title+'</h4><p>'+GROUPS[cg].hint+'</p>'
